{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://shaper.hupu.io/timeflow/schema/batch-report.schema.json",
  "title": "BatchReport",
  "description": "批量上报请求与逐条结果（design §10.3）。批量超限整体拒绝；条目部分成功是正常语义。",
  "$defs": {
    "StreamBatchRequest": {
      "type": "object",
      "additionalProperties": true,
      "required": ["items"],
      "properties": {
        "items": {
          "type": "array",
          "minItems": 1,
          "maxItems": 200,
          "items": {
            "allOf": [
              {"$ref": "stream-update.schema.json"},
              {"type": "object", "required": ["streamKey", "value", "expectedVersion", "requestId"]}
            ]
          }
        }
      }
    },
    "WindowBatchRequest": {
      "type": "object",
      "additionalProperties": true,
      "required": ["items"],
      "properties": {
        "items": {
          "type": "array",
          "minItems": 1,
          "maxItems": 200,
          "items": {"$ref": "window-report.schema.json"}
        }
      }
    },
    "PointBatchRequest": {
      "type": "object",
      "additionalProperties": true,
      "required": ["items"],
      "properties": {
        "items": {
          "type": "array",
          "minItems": 1,
          "maxItems": 200,
          "items": {"$ref": "point-report.schema.json"}
        }
      }
    },
    "CrossEventBatchRequest": {
      "type": "object",
      "additionalProperties": true,
      "required": ["items"],
      "properties": {
        "items": {
          "type": "array",
          "minItems": 1,
          "maxItems": 500,
          "items": {
            "type": "object",
            "additionalProperties": true,
            "required": ["eventId", "sourceType", "sourceId", "targetType", "targetId", "point"],
            "properties": {
              "eventId": {"type": "string", "minLength": 1, "maxLength": 64},
              "sourceType": {"type": "string", "minLength": 1, "maxLength": 32},
              "sourceId": {"type": "string", "pattern": "^[0-9]{1,20}$"},
              "targetType": {"type": "string", "minLength": 1, "maxLength": 32},
              "targetId": {"type": "string", "pattern": "^[0-9]{1,20}$"},
              "point": {"$ref": "point-report.schema.json"}
            }
          }
        }
      }
    },
    "BatchItemResult": {
      "type": "object",
      "additionalProperties": true,
      "required": ["id", "idempotencyKind", "status"],
      "properties": {
        "id": {"type": "string", "minLength": 1, "maxLength": 64},
        "idempotencyKind": {"type": "string", "enum": ["requestId", "eventId"]},
        "status": {"type": "string", "enum": ["accepted", "replayed", "rejected"]},
        "code": {"type": "string", "minLength": 1, "maxLength": 64},
        "message": {"type": "string", "maxLength": 512},
        "retryable": {"type": "boolean"},
        "replayed": {"type": "boolean"},
        "details": {"type": "object", "additionalProperties": true}
      }
    },
    "BatchResult": {
      "type": "object",
      "additionalProperties": true,
      "required": ["results", "accepted", "rejected"],
      "properties": {
        "results": {
          "type": "array",
          "items": {"$ref": "#/$defs/BatchItemResult"}
        },
        "accepted": {"type": "integer", "minimum": 0},
        "rejected": {"type": "integer", "minimum": 0}
      }
    }
  },
  "oneOf": [
    {"$ref": "#/$defs/StreamBatchRequest"},
    {"$ref": "#/$defs/WindowBatchRequest"},
    {"$ref": "#/$defs/PointBatchRequest"},
    {"$ref": "#/$defs/CrossEventBatchRequest"},
    {"$ref": "#/$defs/BatchResult"}
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://shaper.hupu.io/timeflow/schema/business-event.schema.json",
  "title": "BusinessEventRequest",
  "description": "A generic business fact explicitly registered by the owning application. The platform does not infer it from a stream, window or point operation.",
  "type": "object",
  "additionalProperties": false,
  "required": ["streamKey", "kind", "eventTime", "eventId"],
  "properties": {
    "streamKey": {
      "type": "string",
      "minLength": 1,
      "maxLength": 128
    },
    "kind": {
      "type": "string",
      "minLength": 1,
      "maxLength": 128
    },
    "eventTime": {
      "type": "integer",
      "minimum": 0
    },
    "eventId": {
      "type": "string",
      "minLength": 1,
      "maxLength": 64
    },
    "payload": {
      "type": "object"
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://shaper.hupu.io/timeflow/schema/change-delivery-result.schema.json",
  "title": "ChangeDeliveryResult",
  "description": "Fixed callback result schema. APPLIED confirms the complete change set was idempotently applied.",
  "type": "object",
  "additionalProperties": false,
  "required": ["status"],
  "properties": {
    "status": {
      "type": "string",
      "enum": ["APPLIED", "ACCEPTED", "RETRYABLE", "REJECTED"]
    },
    "appliedDigest": {
      "type": "string",
      "pattern": "^sha256:[0-9a-f]{64}$"
    },
    "resultRef": {"type": ["string", "null"], "maxLength": 512},
    "retryAfterMs": {"type": ["integer", "null"], "minimum": 0},
    "code": {"type": ["string", "null"], "maxLength": 128},
    "safeMessage": {"type": ["string", "null"], "maxLength": 512}
  },
  "allOf": [
    {
      "if": {"properties": {"status": {"const": "APPLIED"}}},
      "then": {"required": ["appliedDigest"]}
    },
    {
      "if": {"properties": {"status": {"enum": ["RETRYABLE", "REJECTED"]}}},
      "then": {"required": ["code"]}
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://shaper.hupu.io/timeflow/schema/change-event.schema.json",
  "title": "SequenceChangeEventV1",
  "description": "Immutable, canonical change fact produced by one completed settlement.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "eventId",
    "eventKind",
    "workspaceId",
    "settlementId",
    "scope",
    "interval",
    "definitionVersion",
    "ruleVersions",
    "changes",
    "createdAt",
    "changesDigest",
    "eventDigest"
  ],
  "properties": {
    "schemaVersion": {"const": 1},
    "eventId": {"type": "string", "pattern": "^cev_[0-9a-f]{32}$"},
    "eventKind": {"type": "string", "minLength": 1, "maxLength": 128},
    "workspaceId": {"type": "string", "minLength": 1, "maxLength": 128},
    "settlementId": {"type": "string", "minLength": 1, "maxLength": 128},
    "scope": {"$ref": "#/$defs/scope"},
    "interval": {
      "type": "object",
      "additionalProperties": false,
      "required": ["from", "to"],
      "properties": {
        "from": {"type": "integer", "minimum": 0},
        "to": {"type": "integer", "minimum": 0}
      }
    },
    "definitionVersion": {"type": "integer", "minimum": 1},
    "ruleVersions": {
      "type": "object",
      "additionalProperties": {"type": "integer", "minimum": 1}
    },
    "changes": {
      "type": "array",
      "minItems": 1,
      "items": {"$ref": "#/$defs/change"}
    },
    "createdAt": {"type": "integer", "minimum": 0},
    "changesDigest": {"$ref": "#/$defs/digest"},
    "eventDigest": {"$ref": "#/$defs/digest"}
  },
  "$defs": {
    "scope": {
      "type": "object",
      "additionalProperties": false,
      "required": ["type", "id"],
      "properties": {
        "type": {"type": "string", "minLength": 1, "maxLength": 64},
        "id": {"type": "string", "minLength": 1, "maxLength": 256}
      }
    },
    "change": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "changeId",
        "target",
        "metricId",
        "precision",
        "delta",
        "produced",
        "capped",
        "sourceStreamKeys"
      ],
      "properties": {
        "changeId": {"type": "string", "pattern": "^chg_[0-9a-f]{32}$"},
        "target": {"$ref": "#/$defs/scope"},
        "metricId": {"type": "string", "minLength": 1, "maxLength": 128},
        "precision": {"type": "integer", "minimum": 0, "maximum": 6},
        "delta": {"$ref": "#/$defs/decimal"},
        "produced": {"$ref": "#/$defs/decimal"},
        "capped": {"$ref": "#/$defs/decimal"},
        "sourceStreamKeys": {
          "type": "array",
          "uniqueItems": true,
          "items": {"type": "string", "minLength": 1, "maxLength": 128}
        }
      }
    },
    "decimal": {
      "type": "string",
      "pattern": "^-?(0|[1-9][0-9]*)(\\.[0-9]+)?$"
    },
    "digest": {"type": "string", "pattern": "^sha256:[0-9a-f]{64}$"}
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://shaper.hupu.io/timeflow/schema/definition.schema.json",
  "title": "TimeflowDefinition",
  "description": "配置定义（design §4.3）——接入的唯一入口，也是「配置驱动」的输入。协议单一来源：server DTO 与 SDK DTO 都由本 schema 校验。",
  "type": "object",
  "additionalProperties": true,
  "required": [
    "workspaceId",
    "definitionVersion",
    "protocolVersion",
    "scopeTypes",
    "metrics",
    "maxOfflineTime",
    "stream"
  ],
  "properties": {
    "workspaceId": {
      "type": "string",
      "description": "工作区标识（不透明；平台不解析其内容）",
      "minLength": 1,
      "maxLength": 64
    },
    "definitionVersion": {
      "type": "integer",
      "description": "单调递增；同版本重放返回同一结果",
      "minimum": 1
    },
    "protocolVersion": {
      "type": "integer",
      "description": "协议版本；主版本不兼容直接拒绝",
      "minimum": 1
    },
    "scopeTypes": {
      "type": "array",
      "description": "工作区声明的作用域类型，例如 member、device、subscription、case",
      "minItems": 1,
      "items": {
        "type": "string",
        "pattern": "^[a-z][a-z0-9_]{0,31}$"
      }
    },
    "metrics": {
      "type": "array",
      "description": "可观测或计算的数值维度；平台不假定货币、资源或资产语义",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": true,
        "required": ["metricId", "precision"],
        "properties": {
          "metricId": {
            "type": "string",
            "pattern": "^[a-z][a-z0-9_]{0,63}$"
          },
          "precision": {
            "type": "integer",
            "description": "精度 0..6（0 = 整数货币）；precision=0 时按余数跨段累加、段末结转",
            "minimum": 0,
            "maximum": 6
          },
          "cap": {
            "description": "指标上限（字符串十进制或 null）",
            "type": ["string", "null"],
            "pattern": "^(0|[1-9][0-9]*)(\\.[0-9]+)?$"
          },
          "capScope": {
            "description": "上限执行者与作用域；v1 仅支持 stream（U12）",
            "type": "string",
            "enum": ["stream", "scope"],
            "default": "stream"
          },
          "shared": {
            "type": "boolean",
            "description": "保留字段；v1 拒绝共享指标，跨作用域分配属于下游系统",
            "default": false
          }
        }
      }
    },
    "maxOfflineTime": {
      "type": "integer",
      "description": "业务单次结算最大有效离线时长（ms）；实际值取本值与平台硬上限的较小值，超出则封顶",
      "minimum": 1
    },
    "stream": {
      "type": "array",
      "description": "流定义：平台不解释流的业务含义，只用它匹配上报的 streamKey",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": true,
        "required": ["streamPattern", "metricId", "ruleKey", "ruleVersion", "phases"],
        "properties": {
          "streamPattern": {
            "type": "string",
            "description": "流匹配模式（如 usage:{id}）",
            "minLength": 1,
            "maxLength": 128
          },
          "displayName": {
            "type": "string",
            "description": "资源类型展示名称；仅用于管理和排障",
            "minLength": 1,
            "maxLength": 128
          },
          "metricId": {
            "type": "string",
            "pattern": "^[a-z][a-z0-9_]{0,63}$"
          },
          "ruleKey": {
            "type": "string",
            "minLength": 1,
            "maxLength": 64
          },
          "ruleVersion": {
            "type": "integer",
            "description": "必须显式声明且能在 rule_registry 解析到不可变实现（禁止默认兜底）",
            "minimum": 1
          },
          "carrier": {
            "type": "string",
            "enum": ["interpreter", "spi", "function"]
          },
          "lifecycle": {
            "type": "string",
            "enum": ["finite", "continuous"],
            "default": "finite",
            "description": "finite stream instances end in a zero-rate terminal phase and require a new streamKey for a new instance; continuous streams remain active"
          },
          "artifact": {
            "type": ["string", "null"]
          },
          "phases": {
            "type": "array",
            "description": "解释器可执行的全部内容（受限运算：baseRate / capacity / until）",
            "minItems": 1,
            "items": {
              "type": "object",
              "additionalProperties": true,
              "required": ["name", "baseRate", "until"],
              "properties": {
                "name": {
                  "type": "string",
                  "minLength": 1
                },
                "baseRate": {
                  "type": "string",
                  "description": "基础速率（单位/毫秒），字符串十进制",
                  "pattern": "^-?(0|[1-9][0-9]*)(\\.[0-9]+)?$"
                },
                "capacity": {
                  "description": "相位容量上限（字符串十进制或 null）",
                  "type": ["string", "null"]
                },
                "until": {
                  "type": "object",
                  "description": "相位终止条件——必须**有界**（设计校验 2）",
                  "required": ["kind"],
                  "properties": {
                    "kind": {
                      "type": "string",
                      "enum": ["progress", "event", "immortal"]
                    },
                    "value": {
                      "type": ["string", "number", "null"]
                    }
                  }
                }
              }
            }
          },
          "decay": {
            "type": "array",
            "description": "按离线时长衰减的修正（after 毫秒之后生效）",
            "items": {
              "type": "object",
              "required": ["stat", "op", "value", "after"],
              "properties": {
                "stat": {
                  "type": "string",
                  "enum": ["rate", "capacity"]
                },
                "op": {
                  "type": "string",
                  "enum": ["add", "mul"]
                },
                "value": {
                  "type": "string"
                },
                "after": {
                  "type": "integer",
                  "minimum": 0
                }
              }
            }
          }
        }
      }
    },
    "caps": {
      "type": "object",
      "description": "资源上限速查表（metricId → 字符串十进制）",
      "additionalProperties": {
        "type": "string"
      }
    },
    "tasks": {
      "type": "array",
      "description": "业务自定义定时任务定义（U23 已裁决：去中心化 peer 调度与执行）",
      "items": {
        "type": "object",
        "required": ["taskKey", "cron", "selector", "action"],
        "properties": {
          "taskKey": {
            "type": "string"
          },
          "displayName": {
            "type": "string",
            "description": "任务展示名称；仅用于管理和排障，不参与调度身份",
            "minLength": 1,
            "maxLength": 128
          },
          "cron": {
            "type": "string"
          },
          "timezone": {
            "type": "string",
            "default": "Asia/Shanghai"
          },
          "enabled": {
            "type": "boolean",
            "default": false
          },
          "selector": {"$ref": "#/properties/taskSelector"},
          "action": {"$ref": "#/properties/taskAction"},
          "maxConcurrency": {
            "type": "integer",
            "minimum": 1,
            "maximum": 64
          },
          "batchSize": {
            "type": "integer",
            "minimum": 1,
            "maximum": 2000
          },
          "routeStrategy": {
            "type": "string",
            "enum": ["ROUND_ROBIN", "FAILOVER", "BUSY_OVER"]
          },
          "timeoutMs": {
            "type": "integer",
            "minimum": 100,
            "maximum": 3600000
          },
          "retryLimit": {
            "type": "integer",
            "minimum": 0,
            "maximum": 20
          },
          "misfirePolicy": {
            "type": "string",
            "enum": ["GRACE", "SKIP", "CATCH_UP"]
          }
        }
      }
    },
    "ruleDataFields": {
      "type": "array",
      "description": "Definition-declared ruleData fields that task selectors may reference",
      "items": {"type": "string"}
    },
    "delivery": {
      "type": "object",
      "description": "Optional generic change-event distribution to deployment-bound subscribers.",
      "additionalProperties": false,
      "properties": {
        "enabled": {"type": "boolean", "default": false},
        "mode": {"type": "string", "enum": ["shadow", "live"], "default": "shadow"},
        "includeSourceStreams": {"type": "boolean", "default": true},
        "subscribers": {
          "type": "array",
          "maxItems": 32,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["key", "version", "metrics", "eventKinds"],
            "properties": {
              "key": {"type": "string", "pattern": "^[a-z][a-z0-9_-]{0,127}$"},
              "displayName": {
                "type": "string",
                "description": "回调订阅展示名称；仅用于管理和排障，不参与订阅身份",
                "minLength": 1,
                "maxLength": 128
              },
              "version": {"type": "integer", "minimum": 1},
              "metrics": {
                "type": "array",
                "minItems": 1,
                "uniqueItems": true,
                "items": {"type": "string", "pattern": "^[a-z][a-z0-9_]{0,63}$"}
              },
              "authoritativeMetrics": {
                "type": "array",
                "uniqueItems": true,
                "items": {"type": "string", "pattern": "^[a-z][a-z0-9_]{0,63}$"}
              },
              "eventKinds": {
                "type": "array",
                "minItems": 1,
                "uniqueItems": true,
                "items": {"type": "string", "minLength": 1, "maxLength": 128}
              }
            }
          }
        }
      }
    },
    "events": {
      "type": "array",
      "description": "变化事件类型的展示名称映射；不写入历史事件 payload",
      "maxItems": 128,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["kind", "displayName"],
        "properties": {
          "kind": {"type": "string", "minLength": 1, "maxLength": 128},
          "displayName": {"type": "string", "minLength": 1, "maxLength": 128},
          "description": {"type": "string", "minLength": 1, "maxLength": 256}
        }
      }
    },
    "taskSelector": {
      "type": "object",
      "additionalProperties": false,
      "required": ["scopeType", "limit"],
      "properties": {
        "scopeType": {"type": "string", "minLength": 1},
        "streamPattern": {"type": "string", "minLength": 1},
        "ruleKey": {"type": "string", "minLength": 1},
        "phaseIndexIn": {
          "type": "array",
          "items": {"type": "integer", "minimum": 0},
          "maxItems": 64
        },
        "where": {
          "type": "array",
          "maxItems": 16,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["field", "op", "value"],
            "properties": {
              "field": {"type": "string", "minLength": 1},
              "op": {
                "type": "string",
                "enum": ["eq", "ne", "lt", "lte", "gt", "gte", "in", "prefix"]
              },
              "value": {"type": "string", "minLength": 1}
            }
          }
        },
        "orderBy": {"type": "string", "minLength": 1},
        "limit": {"type": "integer", "minimum": 1, "maximum": 10000}
      }
    },
    "taskAction": {
      "type": "object",
      "additionalProperties": true,
      "required": ["kind"],
      "properties": {
        "kind": {
          "type": "string",
          "enum": ["APPLY_WINDOW", "EMIT_POINT", "TRIGGER_SETTLE", "NOTIFY", "EVICT_CACHE"]
        },
        "metricId": {"type": "string"},
        "streamKeyTemplate": {"type": "string"},
        "stat": {"type": "string", "enum": ["rate", "capacity"]},
        "op": {"type": "string", "enum": ["add", "mul"]},
        "value": {"type": "string"},
        "durationMs": {
          "type": "integer",
          "minimum": 1,
          "description": "APPLY_WINDOW 的持续时间；激活校验要求不超过平台 maxOfflineTime"
        },
        "pointKind": {"type": "string"},
        "source": {"type": "string"},
        "idempotency": {"type": "string", "maxLength": 128}
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://shaper.hupu.io/timeflow/schema/point-report.schema.json",
  "title": "PointReport",
  "description": "时间点事件与值操作上报（design §3.5 / §10.4）。v1 值操作只开放 ADD 与 SET。",
  "type": "object",
  "additionalProperties": true,
  "required": [
    "streamKey",
    "kind",
    "eventTime",
    "eventId"
  ],
  "properties": {
    "streamKey": {
      "type": "string",
      "minLength": 1,
      "maxLength": 128
    },
    "kind": {
      "type": "string",
      "minLength": 1,
      "maxLength": 32
    },
    "eventTime": {
      "type": "integer",
      "minimum": 0
    },
    "ops": {
      "type": "array",
      "maxItems": 64,
      "items": {
        "type": "object",
        "additionalProperties": true,
        "required": ["op", "value"],
        "properties": {
          "op": {
            "type": "string",
            "enum": ["ADD", "SET"]
          },
          "value": {
            "$ref": "#/$defs/decimalSigned"
          }
        }
      }
    },
    "transition": {
      "type": "string",
      "minLength": 1,
      "maxLength": 128
    },
    "eventId": {
      "type": "string",
      "minLength": 1,
      "maxLength": 64
    }
  },
  "$defs": {
    "decimalSigned": {
      "type": "string",
      "pattern": "^-?(0|[1-9][0-9]*)(\\.[0-9]{1,18})?$"
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://shaper.hupu.io/timeflow/schema/protocol-response.schema.json",
  "title": "ProtocolResponse",
  "description": "统一成功/失败响应结构（design §10.2）。retryable 由服务端给出，SDK 不自行推断。",
  "type": "object",
  "additionalProperties": true,
  "required": ["ok"],
  "properties": {
    "ok": {"type": "boolean"},
    "data": {},
    "error": {"$ref": "#/$defs/ProtocolError"},
    "requestId": {"type": "string", "minLength": 1, "maxLength": 128},
    "replayed": {"type": "boolean"}
  },
  "$defs": {
    "ProtocolError": {
      "type": "object",
      "additionalProperties": true,
      "required": ["code", "retryable"],
      "properties": {
        "code": {"type": "string", "minLength": 1, "maxLength": 64},
        "message": {"type": "string", "maxLength": 512},
        "retryable": {"type": "boolean"},
        "retryAfterMs": {"type": "integer", "minimum": 0},
        "details": {"type": "object", "additionalProperties": true}
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://shaper.hupu.io/timeflow/schema/receipt-request.schema.json",
  "title": "ReceiptRequest",
  "description": "报告落地回执（design §10.5 / §13.1）。ACK 可带 appliedDigest；NACK 必带失败原因与是否可重试。",
  "$defs": {
    "appliedDigest": {
      "type": "string",
      "pattern": "^sha256:[0-9a-f]{64}$"
    },
    "AckRequest": {
      "type": "object",
      "additionalProperties": true,
      "required": ["settlementId"],
      "properties": {
        "settlementId": {
          "type": "string",
          "minLength": 1,
          "maxLength": 64
        },
        "appliedDigest": {
          "$ref": "#/$defs/appliedDigest"
        }
      }
    },
    "NackRequest": {
      "type": "object",
      "additionalProperties": true,
      "required": ["settlementId", "code", "message", "retryable"],
      "properties": {
        "settlementId": {
          "type": "string",
          "minLength": 1,
          "maxLength": 64
        },
        "code": {
          "type": "string",
          "minLength": 1,
          "maxLength": 64
        },
        "message": {
          "type": "string",
          "minLength": 1,
          "maxLength": 512
        },
        "retryable": {
          "type": "boolean"
        },
        "details": {
          "type": "object",
          "additionalProperties": true
        }
      }
    }
  },
  "oneOf": [
    {"$ref": "#/$defs/AckRequest"},
    {"$ref": "#/$defs/NackRequest"}
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://shaper.hupu.io/timeflow/schema/report.schema.json",
  "title": "TimeflowSettleReport",
  "description": "SettleReport（design §4.4 / §10.4）——必须自包含：工作区侧只靠这一份报告就能完成落地与对账。",
  "type": "object",
  "additionalProperties": true,
  "required": [
    "settlementId",
    "realDuration",
    "effectiveDuration",
    "segments",
    "gains",
    "losses",
    "capped",
    "events",
    "ruleVersions",
    "definitionVersion",
    "replayed",
    "approximated"
  ],
  "properties": {
    "settlementId": {
      "type": "string",
      "description": "结算标识；工作区侧落地幂等键"
    },
    "realDuration": {
      "type": "integer",
      "minimum": 0,
      "description": "真实离线时长（ms）"
    },
    "effectiveDuration": {
      "type": "integer",
      "minimum": 0,
      "description": "封顶后参与积分的时长（ms）"
    },
    "segments": {
      "type": "array",
      "description": "可解释时间轴——客服 / 对账 / 业务变化明细三处复用同一份数据",
      "items": {
        "type": "object",
        "required": ["from", "to"],
        "properties": {
          "from": { "type": "integer" },
          "to": { "type": "integer" },
          "streamKey": { "type": "string" },
          "metricId": { "type": "string" },
          "phaseIndex": {
            "type": "integer",
            "description": "段内相位序号——解释「这段为什么是这个速率」（对应定义 stream[].phases[phaseIndex]）"
          },
          "rate": { "type": "string" },
          "modifiers": { "type": "object" },
          "produced": { "type": "string" },
          "capped": { "type": "string" },
          "netChange": { "type": "string" },
          "valueStart": { "type": "string", "description": "段起点存量（同一内核段结果）" },
          "valueEnd": { "type": "string", "description": "段终点存量（同一内核段结果）" }
        }
      }
    },
    "gains": {
      "type": "object",
      "description": "只记实际正变化（Σ max(netChange,0)），逐 metricId；容量截断不进 gains",
      "additionalProperties": { "type": "string" }
    },
    "losses": {
      "type": "object",
      "description": "只记负变化（Σ min(netChange,0)）；SET 重置不算 losses",
      "additionalProperties": { "type": "string" }
    },
    "capped": {
      "type": "object",
      "description": "因容量上限未获得的部分，单独可查",
      "additionalProperties": { "type": "string" }
    },
    "events": {
      "type": "array",
      "description": "区间内的事件与值操作（含重置）",
      "items": {
        "type": "object",
        "properties": {
          "streamKey": { "type": "string" },
          "kind": { "type": "string" },
          "eventTime": { "type": "integer" },
          "eventId": { "type": ["string", "null"] },
          "origin": { "type": "string", "enum": ["report", "derived"] },
          "ops": { "type": "array" }
        }
      }
    },
    "ruleVersions": {
      "type": "object",
      "description": "本次结算固化的 ruleKey → ruleVersion（design §19.5）",
      "additionalProperties": { "type": "integer" }
    },
    "definitionVersion": {
      "type": "integer",
      "description": "本次结算使用的定义版本（重放必须用它）"
    },
    "curveApplied": {
      "type": "boolean"
    },
    "replayed": {
      "type": "boolean",
      "description": "幂等回放（命中已完成记录，未重算）"
    },
    "approximated": {
      "type": "boolean",
      "description": "切点降采样近似（超 MAX_CUTS）"
    },
    "cappedByTime": {
      "type": "boolean",
      "description": "是否因 maxOfflineTime 封顶（与 capped 的容量截断区分）；真实时长照记 realDuration"
    },
    "clockRegression": {
      "type": "boolean",
      "description": "是否发生时钟回拨（now < last_settle_time）：本次 effectiveDuration=0、不产出，并记 CLOCK_REGRESSION 审计"
    },
    "netChange": {
      "type": "object",
      "description": "逐资源 Σ netChange（价值守恒 value_end − value_start == Σ netChange 的对外呈现）",
      "additionalProperties": { "type": "string" }
    },
    "streamLifecycles": {
      "type": "array",
      "description": "本次计算确认的资源实例生命周期事实；旧报告缺省为空数组",
      "items": {
        "type": "object",
        "required": ["streamKey", "kind", "state"],
        "properties": {
          "streamKey": { "type": "string" },
          "kind": { "type": ["string", "null"], "enum": ["finite", "continuous", null] },
          "state": {
            "type": "string",
            "enum": ["active", "terminated", "legacy_unknown"]
          },
          "terminalAt": { "type": ["integer", "null"] },
          "terminalReason": {
            "type": ["string", "null"],
            "enum": ["progress", "event", "legacy", null]
          },
          "terminalPhaseIndex": { "type": ["integer", "null"] },
          "terminalValue": { "type": ["string", "null"] },
          "terminalEventId": { "type": ["string", "null"] }
        }
      }
    }
  }
}

